import {SEEDS,ORDERS,orderById,seedById,levelOf,stockCount,deliveryPlan,salePrice} from './engine.mjs';
import {icon,plantArt} from './art.mjs';
const text=(lang,zh,en)=>lang==='zh'?zh:en;
const name=(lang,item)=>lang==='zh'?item.zh:item.en;
const clock=seconds=>`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;
export function orderNeeds(state,order,lang,compact=false){return `<div class="order-needs ${compact?'compact':''}">${Object.entries(order.needs).map(([id,need])=>{const have=stockCount(state,id,order.quality);return `<div class="order-need ${have>=need?'enough':''}"><span class="need-art">${plantArt(id)}</span><span>${name(lang,seedById(id))}<small>${order.quality==='charged'?text(lang,'跑轮作物','Wheel-grown'):text(lang,'任意品质','Any quality')}</small></span><b>${Math.min(have,need)} / ${need}</b></div>`;}).join('')}</div>`;}
export function activeOrderHTML(state,lang,compact=false,now=Date.now()){
 const active=state.activeOrder;
 if(!active){const r=state.lastOrderResult;return `<div class="order-empty">${icon('book',compact?22:30)}<h3>${r?.outcome==='delivered'?text(lang,'这一单，送到啦','Delivery complete'):r?.outcome==='expired'?text(lang,'订单已超时，作物仍保留','Order expired. Your crops are safe.'):text(lang,'先挑一份收成订单','Choose a harvest order')}</h3><p>${r?.outcome==='expired'?text(lang,'仓库和土地都没有扣除作物，可以重新接单。','Nothing was taken from your garden or warehouse. You can accept another order.'):text(lang,'留着交付，还是卖出换种子？由你安排。','Keep your crops for a delivery, or sell them for new seeds. Your choice.')}</p>${compact?`<button class="secondary-button full-width" data-action="nav" data-view="orders">${text(lang,'查看订单与仓库','Orders & warehouse')} ${icon('arrow',13)}</button>`:''}</div>`;}
 const order=orderById(active.id),plan=deliveryPlan(state),left=Math.max(0,Math.ceil((active.expiresAt-now)/1000));
 return `<div class="active-order-content"><div class="order-active-heading"><span class="order-tag ${order.quality==='charged'?'charged':''}">${icon(order.quality==='charged'?'bolt':'book',12)}${order.quality==='charged'?text(lang,'跑轮专送','Wheel delivery'):text(lang,'收成订单','Harvest order')}</span><strong class="order-clock ${left<=30?'urgent':''}" data-order-countdown>${clock(left)}</strong></div><h3>${name(lang,order)}</h3>${orderNeeds(state,order,lang,compact)}<div class="order-prize"><span>${icon('seed',12)} ${order.reward}</span><span>+${order.xp} XP</span></div><div class="order-controls"><button class="primary-button" data-action="deliver-preview" ${!plan.ready?'disabled':''}>${text(lang,'核对并交付','Review delivery')} ${icon('arrow',13)}</button><button class="quiet-button" data-action="cancel-order-confirm">${text(lang,'取消','Cancel')}</button></div><p class="order-small">${text(lang,'交付才扣除作物；超时或取消会保留收成。','Crops are only spent on delivery. Expiry and cancellation keep them safe.')}</p>${compact?`<button class="warehouse-link" data-action="nav" data-view="orders">${text(lang,'打开仓库，安排下一份收成','Open warehouse and plan your crops')} ${icon('arrow',12)}</button>`:''}</div>`;
}
export function inventoryHTML(state,lang){return `<section class="inventory-section"><div class="section-head"><h2>${icon('seed',19)}${text(lang,'收成仓库','Harvest warehouse')}</h2><span>${text(lang,'收获入仓，出售或交付后才扣除','Harvest first. Sell or deliver when you choose.')}</span></div><div class="inventory-grid">${SEEDS.map(s=>`<article class="inventory-card"><div class="inventory-title"><span class="inventory-art">${plantArt(s.id)}</span><div><h3>${name(lang,s)}</h3><p>${text(lang,'累计收获','Lifetime harvests')} ${state.collection[s.id]}</p></div></div>${['normal','charged'].map(quality=>`<div class="inventory-row ${quality}"><span>${icon(quality==='charged'?'bolt':'leaf',13)}${quality==='charged'?text(lang,'跑轮作物','Wheel-grown'):text(lang,'普通作物','Regular')} <b>× ${state.inventory[s.id][quality]}</b></span><button class="sell-button" data-action="sell" data-seed="${s.id}" data-quality="${quality}" ${!state.inventory[s.id][quality]?'disabled':''}>${text(lang,'卖 1 份','Sell 1')} · ${salePrice(s.id,quality)}</button></div>`).join('')}</article>`).join('')}</div><p class="warehouse-note">${text(lang,'出售会减少订单可用库存。普通订单优先使用普通作物，不足时可用跑轮作物，交付前会列出明细。','Selling reduces the stock available for orders. Standard orders use regular crops first and wheel-grown crops if needed; you can review the exact quantities before delivery.')}</p></section>`;}
export function ordersView(state,lang){const level=levelOf(state.xp);return `<section class="view-panel orders-view"><div class="orders-top"><section class="active-order-card"><div class="section-head"><h2>${text(lang,'正在安排的订单','Your current order')}</h2><span>${text(lang,'同时接 1 单','One order at a time')}</span></div><div id="active-order">${activeOrderHTML(state,lang)}</div></section><section class="strategy-note"><span class="eyebrow">FROM WHEEL TO HARVEST</span><h2>${text(lang,'把能量，留给需要的那一株。','Save energy for the crop that matters.')}</h2><ol><li>${text(lang,'先看订单，再安排有限的土地。','Pick an order and plan your available plots.')}</li><li>${text(lang,'4 点跑轮能量灌溉一株，成长 +35%，收获变为跑轮作物。','Irrigate one plant with 4 wheel energy: +35% growth and wheel-grown quality.')}</li><li>${text(lang,'决定收成留下交单，还是直接出售。','Keep the harvest for a delivery or sell it for coins.')}</li></ol><div class="strategy-energy">${icon('bolt',18)}<b id="strategy-energy-value">${state.energy} / 100</b><span>${text(lang,'已储存 · 停转时也能使用','Stored · usable while the wheel is idle')}</span></div><button class="quiet-button" data-action="energy-log">${text(lang,'查看跑轮能量记录','View wheel energy records')} ${icon('arrow',12)}</button></section></div>${inventoryHTML(state,lang)}<section class="order-board"><div class="section-head"><h2>${icon('book',19)}${text(lang,'选一单，慢慢安排','Choose your next delivery')}</h2><span>${text(lang,'确认接单后开始计时','The timer starts when you accept')}</span></div><div class="order-cards">${ORDERS.map(o=>{const locked=level<o.level;return `<article class="order-card ${o.quality==='charged'?'wheel-order':''} ${locked?'locked-order':''}"><div class="order-card-top"><span class="order-tag ${o.quality==='charged'?'charged':''}">${o.quality==='charged'?icon('bolt',12)+text(lang,'跑轮专送','Wheel delivery'):text(lang,'普通订单','Standard order')}</span><span>${o.duration/60} ${text(lang,'分钟','min')}</span></div><h3>${name(lang,o)}</h3><p>${text(lang,o.hint,o.enHint)}</p>${orderNeeds(state,o,lang)}<div class="order-card-bottom"><span>${icon('seed',13)} ${o.reward} <small>+${o.xp} XP</small></span><button class="${locked?'secondary-button':'primary-button'}" data-action="accept-order-preview" data-id="${o.id}" ${locked||state.activeOrder?'disabled':''}>${locked?'Lv. '+o.level:state.activeOrder?text(lang,'已有进行中订单','Order in progress'):text(lang,'接这单','Accept')}</button></div></article>`;}).join('')}</div></section>${state.orderHistory.length?`<section class="delivery-history"><div class="section-head"><h2>${text(lang,'最近的交付','Recent deliveries')}</h2><span>${text(lang,'本地游戏记录','Local game records')}</span></div>${state.orderHistory.slice(0,5).map(h=>`<div class="history-row"><span>${icon('check',14)} ${name(lang,orderById(h.id))}</span><span>${h.chargedUsed?icon('bolt',11)+' '+h.chargedUsed+' · ':''}${new Date(h.at).toLocaleString(lang==='zh'?'zh-CN':'en-US',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}</span></div>`).join('')}</section>`:''}</section>`;}
